package com.turboio.addon;

import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.function.LongSupplier;

/** Bounded resumable read cache. No originals, exports, grants or upload state
 * are modified. Unpublished tails are owned reproducible download bytes only. */
final class AudioDownloads implements AutoCloseable {
 static final long CACHE_TTL=3600000;private static final int STATE_MAX=524288;
 static final class Page {final List<Object> objects;final String next;Page(List<Object> objects,String next){this.objects=Collections.unmodifiableList(objects);this.next=next;}}
 static final class Download {final File file;final Map<String,Object> receipt;final int confirmed,parts;final boolean complete;Download(File file,Map<String,Object> receipt,int confirmed)throws IOException{this.file=file;this.receipt=WireJson.map(WireJson.copy(receipt));this.confirmed=confirmed;parts=(int)AudioUploadWire.number(receipt.get("parts"));complete=file!=null;}}
 private final File root,scope;private final AudioConfig config;private final LifelogAudioArchive.Guard guard;private final long limit;private final int entries;private final FileChannel locking;private final FileLock lock;private boolean closed;
 AudioDownloads(File cache,AudioConfig config,LifelogAudioArchive.Guard guard)throws IOException{this(cache,config,guard,AudioUploadWire.MAX,128);}
 AudioDownloads(File cache,AudioConfig config,LifelogAudioArchive.Guard guard,long limit,int entries)throws IOException{
  check(config!=null&&guard!=null&&limit>=1024&&limit<=AudioUploadWire.MAX&&entries>0&&entries<=128,"AUDIO_DOWNLOAD_CONTEXT");this.config=config;this.guard=guard;this.limit=limit;this.entries=entries;guard.check();File base=cache.getCanonicalFile();safe(base,true);check(base.isDirectory()&&!Files.isSymbolicLink(cache.toPath()),"AUDIO_DOWNLOAD_PATH");root=new File(base,"lifelog-audio-downloads");directory(root);File f=new File(root,".download.lock");safe(f,false);FileChannel channel=FileChannel.open(f.toPath(),StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);FileLock held=null;
  try{try{held=channel.tryLock();}catch(OverlappingFileLockException busy){throw new IOException("AUDIO_DOWNLOAD_BUSY");}check(held!=null,"AUDIO_DOWNLOAD_BUSY");locking=channel;lock=held;File account=new File(root,config.account);check(account.exists()||children(root,97).length<97,"AUDIO_DOWNLOAD_CAPACITY");directory(account);scope=new File(account,config.connection.binding());check(scope.exists()||children(account,128).length<128,"AUDIO_DOWNLOAD_CAPACITY");directory(scope);scan();}catch(IOException|RuntimeException e){if(held!=null)held.release();channel.close();throw e;}
 }
 private static void check(boolean value,String code)throws IOException{AudioUploadWire.check(value,code);}
 private static void safe(File f,boolean dir)throws IOException{check(!Files.isSymbolicLink(f.toPath())&&f.getAbsoluteFile().equals(f.getCanonicalFile()),"AUDIO_DOWNLOAD_PATH");if(f.exists()){check(dir?f.isDirectory():f.isFile(),"AUDIO_DOWNLOAD_PATH");if(!dir)try{Object links=Files.getAttribute(f.toPath(),"unix:nlink",LinkOption.NOFOLLOW_LINKS);check(links instanceof Number&&((Number)links).longValue()==1,"AUDIO_DOWNLOAD_PATH");}catch(UnsupportedOperationException unavailable){throw new IOException("AUDIO_DOWNLOAD_PATH");}}}
 private static void sync(File dir)throws IOException{try(FileChannel c=FileChannel.open(dir.toPath(),StandardOpenOption.READ)){c.force(true);}}
 private static void directory(File f)throws IOException{safe(f,true);if(!f.exists()){check(f.mkdir(),"AUDIO_DOWNLOAD_DIRECTORY");sync(f.getParentFile());}}
 private void current()throws IOException{check(!closed,"AUDIO_DOWNLOAD_CLOSED");guard.check();safe(root,true);safe(scope,true);}
 private void retained(Map<String,Object> receipt,LongSupplier clock)throws IOException{current();check(config.connection.expiresAt>clock.getAsLong(),"AUDIO_CREDENTIAL_EXPIRED");check(AudioUploadWire.time(receipt.get("expires_at"))>clock.getAsLong(),"AUDIO_EXPIRED");}
 private static File[] children(File dir,int maximum)throws IOException{safe(dir,true);File[] files=dir.listFiles();check(files!=null&&files.length<=maximum,"AUDIO_DOWNLOAD_CAPACITY");return files;}
 /** Size/type accounting only for other accounts, never their metadata/audio. */
 private long[] scan()throws IOException{current();long bytes=0,count=0;for(File owner:children(root,97)){if(owner.getName().equals(".download.lock")){safe(owner,false);check(owner.length()==0,"AUDIO_DOWNLOAD_PATH");continue;}check(owner.getName().matches("[a-f0-9]{64}"),"AUDIO_DOWNLOAD_PATH");for(File target:children(owner,128)){check(target.getName().matches("[a-f0-9]{64}"),"AUDIO_DOWNLOAD_PATH");for(File item:children(target,128)){check(item.getName().matches("[a-f0-9]{64}")&&++count<=entries,"AUDIO_DOWNLOAD_CAPACITY");for(File f:children(item,5)){safe(f,false);if(f.getName().equals("payload.partial")||f.getName().equals("payload.bin")){check(f.length()<=AudioUploadWire.MAX,"AUDIO_DOWNLOAD_CAPACITY");bytes=Math.addExact(bytes,f.length());}else{check(Arrays.asList("state.json","state.json.partial","state.json.lock").contains(f.getName())&&f.length()<=STATE_MAX,"AUDIO_DOWNLOAD_PATH");}}}}}check(bytes<=limit,"AUDIO_DOWNLOAD_CAPACITY");return new long[]{bytes,count};}
 private static MaterialApi.Response call(AudioConnection c,String path,MaterialApi.Transport transport,LifelogAudioArchive.Guard guard,LongSupplier clock)throws IOException{
  guard.check();check(c.expiresAt>clock.getAsLong(),"AUDIO_CREDENTIAL_EXPIRED");MaterialApi.Response r=transport.exchange(path,null);guard.check();check(c.expiresAt>clock.getAsLong(),"AUDIO_CREDENTIAL_EXPIRED");if(r.status!=200)throw new IOException(r.status==401?"AUDIO_AUTH_REQUIRED":r.status==403?"AUDIO_SCOPE_REQUIRED":AudioUploadWire.error(r));return r;
 }
 private static void preflight(AudioConnection c,MaterialApi.Transport transport,LifelogAudioArchive.Guard guard,LongSupplier clock)throws IOException{c.readIdentity(call(c,"/identity",transport,guard,clock).body,clock.getAsLong());}
 static Page list(AudioConnection connection,String material,String after,MaterialApi.Transport transport,LifelogAudioArchive.Guard guard,LongSupplier clock)throws IOException{
  check(material!=null&&material.matches("rayneo-lifelog-[a-f0-9]{64}")&&(after==null||after.matches("[a-f0-9]{64}")),"AUDIO_DOWNLOAD_QUERY");preflight(connection,transport,guard,clock);
  try{Map<String,Object> page=WireJson.map(WireJson.read(call(connection,"/material-audio/"+material+"?limit=50"+(after==null?"":"&after="+after),transport,guard,clock).body,262144,20000));AudioUploadWire.keys(page,"material_id","objects","next_after");check(material.equals(page.get("material_id")),"AUDIO_DOWNLOAD_PAGE");List<Object> objects=WireJson.list(page.get("objects"));check(objects.size()<=50,"AUDIO_DOWNLOAD_PAGE");String previous=after==null?"":after;List<Object> result=new ArrayList<>();for(Object raw:objects){Map<String,Object> receipt=AudioDownloadWire.receipt(raw,connection,material,clock.getAsLong(),false);String id=(String)receipt.get("object_id");check(id.compareTo(previous)>0,"AUDIO_DOWNLOAD_PAGE");previous=id;result.add(receipt);}Object next=page.get("next_after");check(next==null||next instanceof String&&objects.size()==50&&previous.equals(next),"AUDIO_DOWNLOAD_PAGE");return new Page(result,(String)next);
  }catch(IllegalArgumentException|ClassCastException invalid){throw new IOException("AUDIO_DOWNLOAD_PAGE");}
 }
 private static boolean same(Object a,Object b){return Arrays.equals(WireJson.bytes(a),WireJson.bytes(b));}
 private static MessageDigest digest(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte n:b)s.append(String.format(Locale.ROOT,"%02x",n&255));return s.toString();}
 private Map<String,Object> state(Object raw,Map<String,Object> receipt,long now)throws IOException{
  try{Map<String,Object> value=WireJson.map(raw);AudioUploadWire.keys(value,"schema","account","binding","receipt","part_hashes","phase","created_at");check(AudioUploadWire.number(value.get("schema"))==1&&config.account.equals(value.get("account"))&&config.connection.binding().equals(value.get("binding"))&&same(receipt,value.get("receipt")),"AUDIO_DOWNLOAD_STATE");long created=AudioUploadWire.number(value.get("created_at"));check(created<=now&&now-created<CACHE_TTL,"AUDIO_DOWNLOAD_CACHE_EXPIRED");List<Object> hashes=WireJson.list(value.get("part_hashes"));check(hashes.size()<=AudioUploadWire.number(receipt.get("parts"))&&Arrays.asList("downloading","ready").contains(value.get("phase")),"AUDIO_DOWNLOAD_STATE");for(Object h:hashes)AudioUploadWire.hash(h);check(!"ready".equals(value.get("phase"))||hashes.size()==AudioUploadWire.number(receipt.get("parts")),"AUDIO_DOWNLOAD_STATE");return value;}catch(IllegalArgumentException|ClassCastException invalid){throw new IOException("AUDIO_DOWNLOAD_STATE");}
 }
 private void save(AtomicDocument document,File directory,Map<String,Object> state)throws IOException{current();document.save(state);sync(directory);current();}
 private String verify(File file,List<Object> hashes,long expected)throws IOException{
  safe(file,false);check(file.isFile()&&file.length()>=expected,"AUDIO_DOWNLOAD_CACHE_CHANGED");MessageDigest all=digest();try(InputStream in=Files.newInputStream(file.toPath(),StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)){byte[] part=new byte[AudioUploadWire.PART];long remaining=expected;for(Object h:hashes){current();int needed=(int)Math.min(remaining,part.length),got=0;while(got<needed){int n=in.read(part,got,needed-got);check(n>0,"AUDIO_DOWNLOAD_CACHE_CHANGED");got+=n;}byte[] bytes=Arrays.copyOf(part,needed);check(TaskWire.hash(bytes).equals(h),"AUDIO_DOWNLOAD_CACHE_CHANGED");all.update(bytes);Arrays.fill(bytes,(byte)0);Arrays.fill(part,(byte)0);remaining-=needed;}check(remaining==0,"AUDIO_DOWNLOAD_STATE");}return hex(all.digest());
 }
 /** Return no file until every byte and the pinned receipt are verified. The
  * caller can schedule another bounded step after a partial result or restart. */
 synchronized Download fetch(Map<String,Object> requested,MaterialApi.Transport transport,LongSupplier clock,int budget)throws IOException{
  current();check(budget>=1&&budget<=32,"AUDIO_DOWNLOAD_BUDGET");Object requestedMaterial=requested==null?null:requested.get("material_id");check(requestedMaterial instanceof String,"AUDIO_DOWNLOAD_QUERY");String material=(String)requestedMaterial;Map<String,Object> receipt=AudioDownloadWire.receipt(requested,config.connection,material,clock.getAsLong(),true);preflight(config.connection,transport,guard,clock);String id=(String)receipt.get("object_id");Map<String,Object> fresh=AudioDownloadWire.receipt(call(config.connection,"/audio/"+id,transport,guard,clock).body,config.connection,material,clock.getAsLong());check(same(fresh,receipt),"AUDIO_DOWNLOAD_RECEIPT_CHANGED");
  long[] usage=scan();File directory=new File(scope,id);safe(directory,true);check(directory.exists()||usage[1]<entries,"AUDIO_DOWNLOAD_CAPACITY");directory(directory);for(File f:children(directory,5)){safe(f,false);check(Arrays.asList("state.json","state.json.partial","state.json.lock","payload.partial","payload.bin").contains(f.getName()),"AUDIO_DOWNLOAD_PATH");}
  File partial=new File(directory,"payload.partial"),ready=new File(directory,"payload.bin");for(File f:new File[]{partial,ready,new File(directory,"state.json"),new File(directory,"state.json.partial"),new File(directory,"state.json.lock")})safe(f,false);
  try(AtomicDocument document=new AtomicDocument(new File(directory,"state.json"),STATE_MAX)){
   Object existing=document.read();Map<String,Object> state;
   if(existing==null){check(!partial.exists()&&!ready.exists(),"AUDIO_DOWNLOAD_UNOWNED");state=WireJson.object("schema",1,"account",config.account,"binding",config.connection.binding(),"receipt",receipt,"part_hashes",new ArrayList<>(),"phase","downloading","created_at",clock.getAsLong());save(document,directory,state);}else state=state(existing,receipt,clock.getAsLong());
   List<Object> hashes=WireJson.list(state.get("part_hashes"));long total=AudioUploadWire.number(receipt.get("bytes")),confirmed=Math.min(total,(long)hashes.size()*AudioUploadWire.PART);check(!(partial.exists()&&ready.exists())&&usage[0]-(partial.length()+ready.length())+total<=limit,"AUDIO_DOWNLOAD_CAPACITY");
   if(ready.exists()){check(hashes.size()==AudioUploadWire.number(receipt.get("parts"))&&ready.length()==total&&verify(ready,hashes,total).equals(receipt.get("sha256")),"AUDIO_DOWNLOAD_CACHE_CHANGED");retained(receipt,clock);state(state,receipt,clock.getAsLong());state.put("phase","ready");save(document,directory,state);retained(receipt,clock);return new Download(ready,receipt,hashes.size());}
   check(!"ready".equals(state.get("phase")),"AUDIO_DOWNLOAD_CACHE_CHANGED");
   if(!partial.exists()){check(confirmed==0,"AUDIO_DOWNLOAD_CACHE_CHANGED");try(FileChannel f=FileChannel.open(partial.toPath(),StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){f.force(true);}sync(directory);}
   check(partial.length()>=confirmed&&partial.length()<=confirmed+AudioUploadWire.PART,"AUDIO_DOWNLOAD_CACHE_CHANGED");verify(partial,hashes,confirmed);
   try(FileChannel disk=FileChannel.open(partial.toPath(),StandardOpenOption.READ,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){
    current();disk.truncate(confirmed);disk.force(true);disk.position(confirmed);
    for(int step=0;step<budget&&confirmed<total;step++){
     retained(receipt,clock);int index=hashes.size();byte[] bytes=AudioDownloadWire.part(call(config.connection,"/audio/"+id+"?index="+index,transport,guard,clock).body,receipt,index);
     try{retained(receipt,clock);check(directory.getUsableSpace()>67108864+bytes.length,"AUDIO_DOWNLOAD_CAPACITY");ByteBuffer block=ByteBuffer.wrap(bytes);while(block.hasRemaining()){current();check(disk.write(block)>0,"AUDIO_DOWNLOAD_WRITE_FAILED");}disk.force(true);retained(receipt,clock);hashes.add(TaskWire.hash(bytes));confirmed+=bytes.length;save(document,directory,state);}finally{Arrays.fill(bytes,(byte)0);}
    }
   }
   if(confirmed<total)return new Download(null,receipt,hashes.size());
   retained(receipt,clock);check(partial.length()==total&&verify(partial,hashes,total).equals(receipt.get("sha256")),"AUDIO_DOWNLOAD_HASH_MISMATCH");retained(receipt,clock);state(state,receipt,clock.getAsLong());Files.move(partial.toPath(),ready.toPath(),StandardCopyOption.ATOMIC_MOVE);sync(directory);state.put("phase","ready");save(document,directory,state);retained(receipt,clock);return new Download(ready,receipt,hashes.size());
  }catch(IllegalArgumentException|ClassCastException invalid){throw new IOException("AUDIO_DOWNLOAD_STATE");}
 }
 /** Only this account/target's validated derived cache, never source or export. */
 synchronized void remove(String object)throws IOException{
  current();check(object!=null&&object.matches("[a-f0-9]{64}"),"AUDIO_DOWNLOAD_QUERY");File dir=new File(scope,object);safe(dir,true);if(!dir.exists())return;File[] files=children(dir,5);if(files.length==0){Files.delete(dir.toPath());sync(scope);return;}File stateFile=new File(dir,"state.json");safe(stateFile,false);check(stateFile.isFile()&&stateFile.length()<=STATE_MAX,"AUDIO_DOWNLOAD_UNOWNED");Map<String,Object> value=WireJson.map(WireJson.read(Files.readAllBytes(stateFile.toPath()),STATE_MAX,20000));long created=AudioUploadWire.number(value.get("created_at"));Map<String,Object> receipt=WireJson.map(value.get("receipt"));receipt=AudioDownloadWire.receipt(receipt,config.connection,(String)receipt.get("material_id"),created,true);state(value,receipt,created);check(object.equals(receipt.get("object_id")),"AUDIO_DOWNLOAD_UNOWNED");for(File f:files){safe(f,false);check(Arrays.asList("state.json","state.json.partial","state.json.lock","payload.partial","payload.bin").contains(f.getName()),"AUDIO_DOWNLOAD_PATH");}for(File f:files)if(!f.equals(stateFile)){current();Files.delete(f.toPath());}current();Files.delete(stateFile.toPath());Files.delete(dir.toPath());sync(scope);
 }
 public synchronized void close()throws IOException{if(!closed){closed=true;try{lock.release();}finally{locking.close();}}}
}
